import re
from pydantic import BaseModel, Field, ValidationError, field_validator


class PhoneNumber(str):
    """Phone number in international form: '+' followed by 8-15 digits.
    Spaces, dots, dashes and parentheses in the input are ignored."""

    @classmethod
    def __get_pydantic_core_schema__(cls, source, handler):
        from pydantic import core_schema

        def validate_phone_number(value, _info):
            if not isinstance(value, str):
                raise TypeError("phone number must be a string")
            compact = re.sub(r"[\s.\-()]", "", value)
            if not re.fullmatch(r"\+\d{8,15}", compact):
                raise ValueError("invalid phone number")
            return cls(compact)

        return core_schema.no_info_plain_validator_function(validate_phone_number)


class SignupForm(BaseModel):
    username: str = Field(pattern=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: PhoneNumber
    password: str = Field(min_length=8)
    password_confirm: str

    model_config = dict(
        extra="forbid"
    )

    @field_validator("email")
    @classmethod
    def email_strip_lower(cls, v: str) -> str:
        if not isinstance(v, str):
            raise TypeError("email must be a string")
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @field_validator("password_confirm")
    @classmethod
    def passwords_match(cls, v, info):
        # We cannot validate password_confirm alone here because we need password value.
        # So we use model_validator below.
        return v

    @classmethod
    def model_validate(cls, data, **kwargs):
        # Use BaseModel.model_validate to parse and validate fields first
        model = super().model_validate(data, **kwargs)
        # Then check password_confirm matches password
        if model.password != model.password_confirm:
            raise ValidationError([{
                'loc': ('password_confirm',),
                'msg': 'passwords do not match',
                'type': 'value_error',
            }], cls)
        return model


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload with pydantic.
    Return dict with keys: username, email, phone (compact form).
    Raise ValidationError (ValueError) for any missing or invalid field.
    """
    form = SignupForm.model_validate(data)
    return {
        "username": form.username,
        "email": form.email,
        "phone": str(form.phone),
    }
